python3 << 'EOF'
import json
import subprocess

# Test that previously working behaviors still work correctly

# Test 1: Valid pipeline with all step types
test_cases = [
    {
        "name": "All step types",
        "test": {
            "pipeline": {"steps": [
                {"op": "select", "columns": ["id", "value"]},
                {"op": "filter", "where": "value > 0"},
                {"op": "map", "as": "double", "expr": "value * 2"},
                {"op": "rename", "mapping": {"value": "original"}},
                {"op": "limit", "n": 100},
                {"op": "branch", "branches": [
                    {"when": "otherwise", "steps": [
                        {"op": "select", "columns": ["id", "double", "original"]}
                    ]}
                ]}
            ]},
            "dataset": [
                {"id": 1, "value": 10},
                {"id": 2, "value": -5},
                {"id": 3, "value": 20}
            ]
        }
    },
    {
        "name": "Complex filter expressions",
        "test": {
            "pipeline": {"steps": [
                {"op": "filter", "where": "id > 0 && value < 100 || name == 'test'"}
            ]},
            "dataset": [
                {"id": 1, "value": 50, "name": "test"},
                {"id": 2, "value": 150, "name": "other"}
            ]
        }
    },
    {
        "name": "Complex map expressions",
        "test": {
            "pipeline": {"steps": [
                {"op": "map", "as": "result", "expr": "id * value + 10"}
            ]},
            "dataset": [
                {"id": 2, "value": 5},
                {"id": 3, "value": 4}
            ]
        }
    }
]

for test_data in test_cases:
    result = subprocess.run(
        ["python", "etl_pipeline.py", "--execute"],
        input=json.dumps(test_data["test"]),
        capture_output=True,
        text=True
    )

    output = json.loads(result.stdout)
    if output["status"] == "ok":
        print(f"✅ {test_data['name']}: rows_in={output['metrics']['rows_in']}, rows_out={output['metrics']['rows_out']}")
    else:
        print(f"❌ {test_data['name']}: {output['error_code']}")
EOF

